create table businesses(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz default now());
create table members(business_id uuid references businesses on delete cascade,user_id uuid references auth.users on delete cascade,role text not null default 'member' check(role in('admin','member')),primary key(business_id,user_id));
create table suppliers(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses on delete cascade,supplier_code text not null,supplier_name text not null,product_category text,contact_name text,contact_email text,status text default 'active',created_at timestamptz default now(),updated_at timestamptz default now(),unique(business_id,supplier_code));
create table purchase_orders(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses on delete cascade,supplier_id uuid not null references suppliers on delete cascade,purchase_order_number text not null,order_date date not null,promised_delivery_date date not null,actual_delivery_date date,ordered_quantity numeric not null check(ordered_quantity>0),received_quantity numeric not null default 0,unit_of_measure text,product_category text,status text,created_at timestamptz default now(),updated_at timestamptz default now(),unique(business_id,purchase_order_number));
create table quality_inspections(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses on delete cascade,supplier_id uuid not null references suppliers,purchase_order_id uuid references purchase_orders,inspection_date date not null,inspected_quantity numeric not null,rejected_quantity numeric not null,defect_reason text,inspection_standard text);
create table risk_alerts(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses on delete cascade,supplier_id uuid references suppliers,purchase_order_id uuid references purchase_orders,severity text,alert_type text,explanation text,evidence_json jsonb,status text default 'New',created_at timestamptz default now(),resolved_at timestamptz);
create table user_actions(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses on delete cascade,alert_id uuid references risk_alerts on delete cascade,user_id uuid references auth.users,action_type text,note text,created_at timestamptz default now());
create table import_jobs(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses on delete cascade,filename text,import_status text,rows_processed int,rows_accepted int,rows_rejected int,error_report_path text,created_at timestamptz default now());
create index on purchase_orders(business_id,supplier_id);create index on purchase_orders(business_id,promised_delivery_date);create index on risk_alerts(business_id,status);
-- Tenant isolation: users only see rows of businesses they belong to.
do $$ declare t text; begin foreach t in array array['suppliers','purchase_orders','quality_inspections','risk_alerts','user_actions','import_jobs'] loop
 execute format('alter table %I enable row level security',t);
 execute format('create policy tenant_isolation on %I using (business_id in (select business_id from members where user_id=auth.uid())) with check (business_id in (select business_id from members where user_id=auth.uid()))',t);end loop;end $$;
